#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — provision or reset the isolated drill paper account (ticket #111).
# Run from anywhere: bash scripts/setup_drill_account.sh
# ──────────────────────────────────────────────────────────────────────────

cd "$(dirname "${BASH_SOURCE[0]}")/.."
ENV_FILE=".env.drill"           # drill keys never go in .env (ADR 0004)
PINS="scripts/accounts.json"
DOCS="docs/ACCOUNTS.md"
TOTAL_STAGES=6

if [[ -n "${ALPACA_API_KEY:-}${ALPACA_SECRET_KEY:-}" ]]; then
  warn "ALPACA_API_KEY / ALPACA_SECRET_KEY are exported in this shell."
  warn "alpaca.sh refuses a process holding both pairs; unset them and re-run:"
  note "  unset ALPACA_API_KEY ALPACA_SECRET_KEY"
  exit 6
fi

banner "Drill paper account setup"

# ── 1. E2BOT routines ──────────────────────────────────────────────────────
stage "Identify the E2BOT routines"
say "Three 'E2BOT' routines are Active in the Claude cloud workspace and no"
say "repository here references them (docs/ROUTINE-VERIFICATION.md). Before a"
say "second paper account exists, confirm what they are attached to."
open_url "https://claude.ai/code"
step "Open Routines. For each E2BOT routine note its repository and whether its"
step "environment carries ALPACA_API_KEY (production) or a different pair."
ask E2BOT_NOTE "One line: what the E2BOT routines are attached to (repo / key pair / none):"
[[ -n "$E2BOT_NOTE" ]] || { warn "a note is required; re-run when known"; exit 1; }
printf -- '- %s: %s\n' "$(date -u +%F)" "$E2BOT_NOTE" >> "$DOCS"
printf '  %s✓ recorded%s in %s\n' "$GREEN" "$RESET" "$DOCS"
confirm "Will the E2BOT routines never receive the DRILL_* keys you are about to create?" \
  || { warn "stop: the drill account would not be isolated"; exit 1; }

# ── 2. Create the account ──────────────────────────────────────────────────
stage "Open a new paper account"
say "Alpaca allows up to three paper accounts per login; this creates the second."
open_url "https://app.alpaca.markets/paper/dashboard/overview"
step "Click the paper account number in the top-left corner."
step "Choose 'Open New Paper Account'. Starting equity is fixed at \$100,000."
step "Switch the dashboard to the NEW account (its number in the top-left changes)."
note "If 'Open New Paper Account' is missing, the 3-account cap is reached:"
note "delete an unused paper account first (Account Settings → Delete Account)."
pause "Done, and the new account is selected?"

# ── 3. Keys ────────────────────────────────────────────────────────────────
stage "Generate the drill account's API keys"
say "Keys are per account. Make sure the NEW account is selected before generating."
open_url "https://app.alpaca.markets/paper/dashboard/overview"
step "On the overview page, 'API Keys' → 'Generate New Keys' (or 'Regenerate')."
step "Copy the Key ID and the Secret; the secret is shown once."
ask_secret DRILL_ALPACA_API_KEY "Paste the drill Key ID:"
ask_secret DRILL_ALPACA_SECRET_KEY "Paste the drill Secret Key:"
[[ -n "$DRILL_ALPACA_API_KEY" && -n "$DRILL_ALPACA_SECRET_KEY" ]] || { warn "both values are required"; exit 1; }
write_env DRILL_ALPACA_API_KEY "$DRILL_ALPACA_API_KEY"
write_env DRILL_ALPACA_SECRET_KEY "$DRILL_ALPACA_SECRET_KEY"
note ".env.drill is gitignored (.env.* rule)."

# ── 4. GitHub secrets ──────────────────────────────────────────────────────
stage "Store the pair as GitHub Actions secrets"
say "Drill workflows (later tickets) read DRILL_* only; production workflows"
say "keep ALPACA_* and must never see these names."
set_secret DRILL_ALPACA_API_KEY "$DRILL_ALPACA_API_KEY"
set_secret DRILL_ALPACA_SECRET_KEY "$DRILL_ALPACA_SECRET_KEY"

# ── 5. Pin the account ─────────────────────────────────────────────────────
stage "Read the new account and pin it"
say "Read-only GET /v2/account under the drill profile; nothing is written to the broker."
ACCOUNT_JSON=$(ALPACA_PROFILE=drill bash scripts/alpaca.sh account) \
  || { warn "alpaca.sh account failed under the drill profile; check the keys and re-run"; exit 1; }
read -r DRILL_NUMBER DRILL_ID < <(printf '%s' "$ACCOUNT_JSON" | python3 -c '
import json, sys
d = json.load(sys.stdin)
print(d["account_number"], d["id"])')
PROD_NUMBER=$(python3 -c '
import json; print(json.load(open("'"$PINS"'"))["production"]["account_number"])')
if [[ "$DRILL_NUMBER" == "$PROD_NUMBER" ]]; then
  warn "these keys answer as the PRODUCTION account ($PROD_NUMBER)."
  warn "You generated keys for the wrong account. Delete .env.drill, select the"
  warn "new account in the dashboard, and re-run from stage 3."
  rm -f "$ENV_FILE"
  exit 8
fi
say "Drill account: $DRILL_NUMBER ($DRILL_ID)"
python3 scripts/account_pin.py set drill "$DRILL_NUMBER" "$DRILL_ID"
python3 - "$DOCS" "$DRILL_NUMBER" "$DRILL_ID" "$(date -u +%FT%TZ)" <<'PY'
import sys
path, number, ident, stamp = sys.argv[1:]
text = open(path).read()
rows = {"| `account_number` |": number, "| `id` |": ident, "| `created_at` |": stamp}
out = []
for line in text.splitlines():
    for prefix, value in rows.items():
        if line.startswith(prefix):
            cells = line.split("|")
            cells[-2] = f" `{value}` "
            line = "|".join(cells)
    out.append(line)
open(path, "w").write("\n".join(out) + "\n")
PY
printf '  %s✓ pinned%s drill in %s and %s\n' "$GREEN" "$RESET" "$PINS" "$DOCS"

# ── 6. Done check ──────────────────────────────────────────────────────────
stage "Verify both profiles"
say "Ticket #111 is done when the drill profile returns the new account and"
say "production is unchanged. Both calls are read-only."
ALPACA_PROFILE=drill bash scripts/alpaca.sh verify-account; echo
bash scripts/alpaca.sh verify-account; echo
say "Commit the pin and the docs table:"
note "  git add $PINS $DOCS && git commit -m 'drill account: pin $DRILL_NUMBER'"
say "Then close ticket #111 with the two verify-account lines above."

finish
